const treeGrid = window.mainPage.getTreeGrid();
  const selectedRowIds = treeGrid.settings.selectedRows;
if (selectedRowIds.length === 0) {
	options.tgvContext.grid.expandAll();
	return;
}

const grid = options.tgvContext.grid;
const indexTreeRows = treeGrid.settings.indexTreeRows;
const selectedSet = new Set(selectedRowIds);
const childToParent = new Map();
for (const [parentId, children] of Object.entries(indexTreeRows)) {
	if (parentId === 'roots') {
		continue;
	};
	for (const childId of children) {
		childToParent.set(childId, parentId);
	}
}

const topmostSelectedIds = selectedRowIds.map((rowId) => {
	let topmostSelected = rowId;
	let currentId = rowId;

	while (childToParent.has(currentId)) {
		currentId = childToParent.get(currentId);
		if (selectedSet.has(currentId)) {
			topmostSelected = currentId;
		}
	}
	return topmostSelected;
});

const uniqueTopmostIds = [...new Set(topmostSelectedIds)];
options.getActions().updateSelectedRows(uniqueTopmostIds);

const promises = uniqueTopmostIds.map((rowId) => grid.expand(rowId));
Promise.all(promises);
